/**
 * Config metadata generated by the compiler extension (`@znight/config/compiler`) under
 * `metadata.extensions.config`. See docs/internals/architecture.md §9.3.
 */
import type { Token } from '@znight/core'

/**
 * Type of a config property, derived from its TypeScript type by the compiler:
 *
 * | TypeScript                           | Field type  |
 * | ------------------------------------ | ----------- |
 * | `string`, string literal union       | `string`    |
 * | `number`, number literal union       | `number`    |
 * | `boolean`                            | `boolean`   |
 * | `string[]` (or literal element union)| `string[]`  |
 * | `number[]`                           | `number[]`  |
 * | `URL`                                | `url`       |
 * | objects, records, `unknown`          | `json`      |
 */
export type ConfigFieldType = 'string' | 'number' | 'boolean' | 'string[]' | 'number[]' | 'url' | 'json'

/** Every supported {@link ConfigFieldType}. */
export const CONFIG_FIELD_TYPES: readonly ConfigFieldType[] = Object.freeze([
  'string',
  'number',
  'boolean',
  'string[]',
  'number[]',
  'url',
  'json',
])

/** Allowed value of an enum-like property (`'dev' | 'prod'`, `1 | 2`). */
export type ConfigEnumValue = string | number | boolean

/** One property of a config class. */
export interface ConfigFieldDefinition {
  /** Property name on the config class. */
  readonly property: string
  /** Environment variable name (`@Env(name)` / `@Secret(name)`, else `PREFIX_PROPERTY`). */
  readonly env: string
  /** Key path in structured sources (`@Key(path)`, else `prefix.property`). */
  readonly key: string
  readonly type: ConfigFieldType
  /** Allowed values (literal union types). For arrays, every element must be allowed. */
  readonly enum?: readonly ConfigEnumValue[]
  /**
   * `@Default(value)`, coerced like a source value. Initializers are kept by the instance itself
   * (a statically evaluated initializer may be emitted here too: same result).
   */
  readonly default?: unknown
  /** `false` when the property is optional, has a default or an initializer. */
  readonly required: boolean
  /** `@Secret`: masked in serialisation, `util.inspect`, `toString` and error messages. */
  readonly secret: boolean
}

/** A config class (`@Config(prefix?)`), registered as a singleton provider. */
export interface ConfigClassDefinition {
  /** Provider token of the class. */
  readonly token: Token
  readonly prefix?: string
  readonly fields: readonly ConfigFieldDefinition[]
}

/** `metadata.extensions.config`. */
export interface ConfigMetadata {
  /** Every config class of the application, ordered by token. */
  readonly configs: readonly ConfigClassDefinition[]
}

declare module '@znight/core' {
  interface ZnightExtensionsMetadata {
    readonly config?: ConfigMetadata
  }
}
